(7163689, 1100003, 112828, '<td valign="top">Interesting, I think this is the first shisha image I''ve seen on DPC.<br/> <br/>Very cool composition, great expressions.</td>', 'Interesting, I think this is the first shisha image I''ve seen on DPC. Very cool composition, great expressions.', '2014-01-27 21:54:50.000000', NULL, 1),
(7163691, 1099924, 112828, '<td valign="top">Nice hooter! ;)<br/> <br/>I don''t love the bokeh on the branches in the rear, as they show major edge sharpening.  Otherwise though, quite nice.</td>', 'Nice hooter! ;) I don''t love the bokeh on the branches in the rear, as they show major edge sharpening.  Otherwise though, quite nice.', '2014-01-27 21:59:21.000000', NULL, 1),
(7163692, 1100151, 112828, '<td valign="top">Interesting candid moment between the coach and team.</td>', 'Interesting candid moment between the coach and team.', '2014-01-27 21:59:38.000000', NULL, 1),
(7163696, 1100150, 112828, '<td valign="top">Nice image - the figures are a tad smaller than I''d like in relationship to the overall composition (making the birds seem nearly human-sized), and the colors aren''t quite where I want them to be (seems a bit green overall) - however, it really is a lovely image all the same.</td>', 'Nice image - the figures are a tad smaller than I''d like in relationship to the overall composition (making the birds seem nearly human-sized), and the colors aren''t quite where I want them to be (seems a bit green overall) - however, it really is a lovely image all the same.', '2014-01-27 22:00:48.000000', NULL, 1),
(7163697, 1099650, 112828, '<td valign="top">Best looking hooter I''ve seen yet.  Love the eye.</td>', 'Best looking hooter I''ve seen yet.  Love the eye.', '2014-01-27 22:01:07.000000', NULL, 1),
(7163698, 1099904, 112828, '<td valign="top">Swamp music!  Nice balance and symmetry.</td>', 'Swamp music!  Nice balance and symmetry.', '2014-01-27 22:01:36.000000', NULL, 1),
