(7164365, 1100059, 96530, '<td valign="top">Very nice capture of a pretty woman in the moment.</td>', 'Very nice capture of a pretty woman in the moment.', '2014-01-28 19:30:37.000000', NULL, 1),
(7164366, 1099680, 96530, '<td valign="top">Beautiful scene. Would have been a scary capture to get unless you were safe in a vehicle maybe? I''m thinking no long lens would get you a safe enough distance from this fast runner. Good luck!</td>', 'Beautiful scene. Would have been a scary capture to get unless you were safe in a vehicle maybe? I''m thinking no long lens would get you a safe enough distance from this fast runner. Good luck!', '2014-01-28 19:35:05.000000', NULL, 1),
