(7164391, 1100114, 96530, '<td valign="top">Great space and very well captured.</td>', 'Great space and very well captured.', '2014-01-28 20:09:09.000000', NULL, 1),
(7164392, 1100063, 96530, '<td valign="top">Beautiful shot. I assume it''s on some sort of velvety leaf, but I thought it was astroturf at first ;) Best of luck to you.</td>', 'Beautiful shot. I assume it''s on some sort of velvety leaf, but I thought it was astroturf at first ;) Best of luck to you.', '2014-01-28 20:11:09.000000', NULL, 1),
