(7172120, 1098217, 49018, '<td valign="top">Nice, I was going to call it a wonderful juxtaposition, but on second look there is no person behind the dog, just him. Good image.</td>', 'Nice, I was going to call it a wonderful juxtaposition, but on second look there is no person behind the dog, just him. Good image.', '2014-02-07 14:17:17.000000', NULL, 0),
(7172122, 1100131, 49018, '<td valign="top">Excellent, excellent. Pragmatically to the point.</td>', 'Excellent, excellent. Pragmatically to the point.', '2014-02-07 14:18:11.000000', NULL, 0),
(7172149, 1099656, 69684, '<td valign="top">I wouldn''t worry too much about the score. As said by many others the geometric shapes are great here. Perhaps the whole is just too busy. Congrats with your "Tiny violin" and the comment from <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/31.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/31.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/31.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=27482" rel="nofollow" target="_blank">LalliSig</a>, I didn''t knew he (one of my favorites) was active here again ;)</td>', 'I wouldn''t worry too much about the score. As said by many others the geometric shapes are great here. Perhaps the whole is just too busy. Congrats with your "Tiny violin" and the comment from  LalliSig, I didn''t knew he (one of my favorites) was active here again ;)', '2014-02-07 15:04:34.000000', NULL, 0),
(7172205, 1099644, 104230, '<td valign="top">Tack sharp and wonderful detail and colors against a muted and blurry background. Just Wonderful.</td>', 'Tack sharp and wonderful detail and colors against a muted and blurry background. Just Wonderful.', '2014-02-07 16:10:24.000000', NULL, 0),
